use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.board();
    var first = true;
    for dish in board {
        if first {
            first = false;
        } else {
            io.write(text: ";")?;
        }
        kitchen.serve(dish: dish, io: io)?;
    }
    return Ok(unit);
}

use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var first = true;
    var index = 0;
    while index < board.len() {
        let dish = board.get(index: index)?;
        if first {
            first = false;
        } else {
            io.write(text: ";")?;
        }
        galley.kitchen.serve(dish: dish, io: io)?;
        index = index + 1;
    }
    return Ok(unit);
}

